// Normalize seven evidence sources into one chronological timeline scoped
// to the correlation window, with a naive proximity-to-incident score per event.
const cfg = $('Set - Config').first().json;
const all = $input.first().json;

const logsData = all.logs || all[0] || {};
const metricsData = all.metrics || all[1] || {};
const tracesData = all.traces || all[2] || {};
const commitsData = all.commits || all[3] || [];
const prsData = all.pulls || all[4] || [];
const infraData = all.infra || all[5] || {};
const deploysData = all.deployments || all[6] || {};

const incidentStart = new Date(cfg.incidentStartedAt).getTime();
const windowStart = incidentStart - cfg.correlationWindowMinutes * 60 * 1000;

function proximityScore(ts) {
  if (!ts || isNaN(ts)) return 0;
  const distanceMinutes = Math.abs(incidentStart - ts) / 60000;
  return Math.max(0, Math.round(100 - distanceMinutes));
}

const events = [];

for (const l of (logsData.entries || logsData.logs || [])) {
  const ts = new Date(l.timestamp || l.time).getTime();
  events.push({ type: 'log', timestamp: ts, summary: (l.message || '').slice(0, 300), level: l.level, proximityScore: proximityScore(ts) });
}

for (const anomaly of (metricsData.anomalies || [])) {
  const ts = new Date(anomaly.timestamp).getTime();
  events.push({ type: 'metric_anomaly', timestamp: ts, summary: (anomaly.metric || '') + ' ' + (anomaly.description || ''), proximityScore: proximityScore(ts) });
}

for (const trace of (tracesData.traces || [])) {
  const ts = new Date(trace.startTime || trace.timestamp).getTime();
  events.push({ type: 'trace_error', timestamp: ts, summary: (trace.operationName || '') + ' - ' + (trace.errorMessage || ''), proximityScore: proximityScore(ts) });
}

for (const c of (Array.isArray(commitsData) ? commitsData : [])) {
  const ts = new Date(c.commit?.author?.date || c.commit?.committer?.date).getTime();
  events.push({ type: 'commit', timestamp: ts, summary: (c.commit?.message || '').split('\n')[0], sha: c.sha, author: c.commit?.author?.name, proximityScore: proximityScore(ts) });
}

for (const pr of (Array.isArray(prsData) ? prsData : [])) {
  const ts = new Date(pr.merged_at || pr.updated_at).getTime();
  if (!pr.merged_at) continue;
  events.push({ type: 'pull_request', timestamp: ts, summary: '#' + pr.number + ' ' + pr.title, url: pr.html_url, proximityScore: proximityScore(ts) });
}

for (const change of (infraData.changes || [])) {
  const ts = new Date(change.timestamp).getTime();
  events.push({ type: 'infra_change', timestamp: ts, summary: (change.action || '') + ' on ' + (change.resource || '') + ' by ' + (change.actor || ''), proximityScore: proximityScore(ts) });
}

for (const d of (deploysData.deployments || (Array.isArray(deploysData) ? deploysData : []))) {
  const ts = new Date(d.deployedAt || d.timestamp).getTime();
  events.push({ type: 'deployment', timestamp: ts, summary: 'Deployed ' + (d.version || d.ref || 'unknown') + ' to ' + (d.environment || 'production'), proximityScore: proximityScore(ts) });
}

const windowedEvents = events
  .filter(e => e.timestamp && e.timestamp >= windowStart && e.timestamp <= incidentStart + 15 * 60 * 1000)
  .sort((a, b) => a.timestamp - b.timestamp)
  .map(e => ({ ...e, timestampIso: new Date(e.timestamp).toISOString() }));

const eventCountsByType = windowedEvents.reduce((acc, e) => { acc[e.type] = (acc[e.type] || 0) + 1; return acc; }, {});

return [{
  json: {
    ...cfg,
    timeline: windowedEvents,
    eventCountsByType,
    totalEventsInWindow: windowedEvents.length
  }
}];

const prior = $('JS - Build Unified Timeline & Correlate Events').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { hypotheses: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { hypotheses: [], parseError: true };
}

const hypothesesWithEvidence = (parsed.hypotheses || []).map(h => ({
  ...h,
  citedEvents: (h.citedEventIndexes || []).map(i => prior.timeline[i]).filter(Boolean)
}));

return [{
  json: {
    ...prior,
    hypotheses: hypothesesWithEvidence,
    topHypothesis: hypothesesWithEvidence[0] || null
  }
}];

const prior = $('JS - Parse Root Cause Analysis').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { evidenceRanking: [], remediationPlan: { riskLevel: 'medium', steps: [], rollbackAvailable: false, rollbackDescription: '', estimatedRecoveryMinutes: 0 }, planSummary: '' };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed.parseError = true;
}

const whatsappMessage = '🔎 Root Cause Report — ' + prior.incidentId + '\n' +
  'Service: ' + prior.serviceName + '\n' +
  'Top hypothesis: ' + (prior.topHypothesis?.rootCause || 'unknown') + ' (' + (prior.topHypothesis?.confidencePercent || 0) + '% confidence, ' + (prior.topHypothesis?.category || 'unknown') + ')\n' +
  'Reasoning: ' + (prior.topHypothesis?.reasoning || '') + '\n\n' +
  'Remediation plan (' + (parsed.remediationPlan?.riskLevel || 'unknown').toUpperCase() + ' risk, ~' + (parsed.remediationPlan?.estimatedRecoveryMinutes || '?') + ' min to recover):\n' +
  (parsed.remediationPlan?.steps || []).map((s, i) => (i + 1) + '. ' + s).join('\n') + '\n\n' +
  'Reply EXECUTE to run this plan or DISMISS to log it without action.';

return [{
  json: {
    ...prior,
    evidenceRanking: parsed.evidenceRanking || [],
    remediationPlan: parsed.remediationPlan || {},
    planSummary: parsed.planSummary || '',
    whatsappMessage
  }
}];

const state = $('WhatsApp - Send Remediation Started').first().json;
const metrics = $input.first().json;

const errorRate = Number(metrics.errorRatePercent ?? metrics.error_rate ?? 0);
const p95LatencyMs = Number(metrics.p95LatencyMs ?? metrics.latency_p95 ?? 0);
const uptimePercent = Number(metrics.uptimePercent ?? metrics.uptime ?? 100);
const resolved = errorRate < 1 && p95LatencyMs < 800 && uptimePercent >= 99.5;

return [{ json: { ...state, errorRate, p95LatencyMs, uptimePercent, incidentResolved: resolved } }];
